 function recordPlanningHistory(label){const history=historyForScope(),state=conceptSnapshot();if(!history||!state)return;history.undo.push({label,state});if(history.undo.length>PLANNING_HISTORY_LIMIT)history.undo.shift();history.redo=[];updateHistoryControls()}
