function renderTerrainReadouts(){const routeId=$('planningDrivewayFeature')?.value,siteId=$('planningBuildSiteFeature')?.value,drive=planning?.drivewayAnalyses?.[routeId],site=planning?.buildSiteAnalyses?.[siteId],driveout=$('drivewayEstimateReadout'),siteout=$('buildSiteReadout');if(driveout)driveout.innerHTML=drive?`<b>${safe(drive.classification)}</b> - ${drive.lengthFeet.toLocaleString()} ft - <b>${money(drive.low)}-${money(drive.high)}</b><br>Expected: ${money(drive.expected)} | Basis: <b>${safe(drive.estimateBasis||'Manual terrain')}</b> | Inputs: ${safe(drive.terrainClass)}, ${safe(drive.surface)}, ${drive.averageSlope||'slope unknown'}% manual average.<br><span class="small">Drivers: ${safe((drive.drivers||[]).join(', ')||'route length and terrain')}. Calculated ${new Date(drive.calculatedAt).toLocaleString()}.</span>`:'Draw and select a driveway route to calculate a property-specific range.';renderTerrainElevation(routeId);renderTerrainComparison();if(siteout)siteout.innerHTML=site?`<b>${safe(site.classification)}</b> - ${site.areaAcres?.toFixed(2)||'0.00'} ac outlined<br>${safe(site.terrainNote||'Terrain not entered.')} ${safe(site.utilityNote||'')}<br><span class="small">Septic: ${safe(site.septicStatus||'unknown')} - user-entered assessment, updated ${new Date(site.updatedAt).toLocaleString()}.</span>`:'Draw and select one or more build-site areas to compare them.'}
