 function saveTerrainDriveway(message='Driveway feasibility and range estimate saved for this property.',options={}){const id=$('planningDrivewayFeature').value,feature=planning?.features.find(item=>item.id===id);if(!feature){status('Draw and select a driveway route first.');return false}if(options.recordHistory!==false)recordPlanningHistory(`updating driveway feasibility for ${feature.label}`);const input=terrainDrivewayInput(feature),estimate=estimateDriveway(input),profile=terrainProfile(id);planning.drivewayAnalyses[id]={...input,...estimate,elevationProfileFingerprint:profile?.geometryFingerprint||'',elevationProfileStale:!!(profile&&!terrainProfileCurrent(feature,profile))};savePlan(`Updated driveway feasibility for ${feature.label}`);renderFeatures();status(message);return true}
 async function requestTerrainElevation(){const id=$('planningDrivewayFeature')?.value,feature=planning?.features.find(item=>item.id===id),button=$('requestElevationProfileBtn'),scope=historyScope();if(!feature){status('Draw and select a driveway route first.');return}if(!window.OTElevation?.getElevationProfile){status('The elevation adapter did not load. Manual terrain estimates remain available.');return}if(button)button.disabled=true;status('Locating preliminary elevations along the full driveway route...');const profile=await window.OTElevation.getElevationProfile(feature.geometry.coordinates);if(scope!==historyScope()||!planning?.features.some(item=>item.id===id)){if(button)button.disabled=false;status('The active property or concept changed, so the returned profile was not applied.');return}recordPlanningHistory(`updating elevation profile for ${feature.label}`);planning.elevationProfiles=planning.elevationProfiles||{};planning.elevationProfiles[id]={...profile,stale:false,lastRequestedAt:now()};if(profile.success){saveTerrainDriveway(profile.cached?'Reused the unchanged cached elevation profile and refreshed the driveway estimate.':'Measured elevation profile saved and applied to the driveway estimate.',{recordHistory:false})}else{saveTerrainDriveway('Elevation retrieval did not complete. Manual terrain planning was preserved; see the profile message for details.',{recordHistory:false})}if(button)button.disabled=false}
function fillTerrainDrivewayInputs(){fillDrivewayInputs();const id=$('planningDrivewayFeature')?.value,manual=planning?.manualElevationOverrides?.[id];if(!id)return;$('planningManualElevationEnabled').checked=!!manual?.enabled;setField('planningStartElevation',manual?.startElevationFeet);setField('planningEndElevation',manual?.endElevationFeet);setField('planningManualElevationNote',manual?.note)}
 function choosePreferredDriveway(){const id=$('planningPreferredRoute')?.value;if(!planning?.features.some(feature=>feature.id===id&&feature.type==='driveway-route')){status('Select a driveway route in this concept first.');return}recordPlanningHistory('choosing preferred driveway route');planning.preferredDrivewayRouteId=id;const concept=activeConcept();if(concept)concept.preferredDrivewayRouteId=id;savePlan('Marked preferred driveway route');renderFeatures();status('Preferred driveway route saved for this concept.')}
 function editTerrainGeometry(){const feature=selectedFeature();if(!feature){status('Select a saved planning feature first.');return}clearVertices();vertexGroup=L.featureGroup().addTo(MAP());feature.geometry.coordinates.forEach((coord,index)=>{const marker=L.marker([coord.lat,coord.lng],{draggable:true,title:`Vertex ${index+1}`}).addTo(vertexGroup);marker.on('dragstart',()=>{recordPlanningHistory(`adjusting ${FEATURE_NAMES[feature.type].toLowerCase()} geometry`);vertexDragMapWasEnabled=!!MAP()?.dragging?.enabled?.();if(vertexDragMapWasEnabled)MAP()?.dragging?.disable()});marker.on('dragend',event=>{if(vertexDragMapWasEnabled){MAP()?.dragging?.enable();vertexDragMapWasEnabled=false}const next=event.target.getLatLng();feature.geometry.coordinates[index]=point(next.lat,next.lng);feature.updatedAt=now();markTerrainProfileStale(feature);savePlan(`Adjusted ${FEATURE_NAMES[feature.type].toLowerCase()} geometry`);renderFeatures();status(feature.type==='driveway-route'?'Geometry saved. Its elevation profile is now stale and will not affect the estimate until refreshed.':'Geometry saved. Drag another vertex or choose Edit geometry again when finished.')})});status('Drag the visible vertex handles to edit. Map panning pauses while a vertex is being moved.')}
 function deleteTerrainFeature(){const feature=selectedFeature();if(!feature)return;const dependent=planning.features.filter(item=>(item.relationships||[]).includes(feature.id));if(!confirm(`Delete ${feature.label}? This removes only this planning feature from ${activeProperty()?.name||'this property'}${dependent.length?` and clears ${dependent.length} related feature link${dependent.length===1?'':'s'}`:''}.`))return;recordPlanningHistory(`deleting ${FEATURE_NAMES[feature.type].toLowerCase()}`);planning.features=planning.features.filter(item=>item.id!==feature.id);planning.features.forEach(item=>{item.relationships=(item.relationships||[]).filter(id=>id!==feature.id)});delete planning.drivewayAnalyses[feature.id];delete planning.buildSiteAnalyses[feature.id];delete planning.utilityAnalyses?.[feature.id];delete planning.elevationProfiles?.[feature.id];delete planning.manualElevationOverrides?.[feature.id];if(planning.preferredDrivewayRouteId===feature.id)planning.preferredDrivewayRouteId='';const concept=activeConcept();if(concept?.preferredDrivewayRouteId===feature.id)concept.preferredDrivewayRouteId='';selectedFeatureId='';clearVertices();savePlan(`Deleted ${FEATURE_NAMES[feature.type].toLowerCase()}`);renderFeatures();status('Planning feature deleted. Associated driveway profile and route preference were reconciled.')}
