function updateToolbar(){const active=$('planningActiveTool'),cancel=$('planningCancelDrawBtn');if(active)active.textContent=drawing?FEATURE_NAMES[drawing.type]||drawing.type:'Navigate';if(cancel)cancel.hidden=!drawing}
 function selectToolbarTool(type){if(type==='select'){cancelDrawing();status('Select a feature on the map to edit it, or click open map space to deselect it.');return}if(type==='measure'){clearVertices();lastDrawingClick=null;drawing={type:'measure',geometry:'LineString',coordinates:[]};setDrawingMapInteraction(true);status('Measure: click map points, then Finish. This measurement is not saved.');updateToolbar();return}const select=$('planningFeatureType');if(select&&[...select.options].some(option=>option.value===type))select.value=type;else if(select){const option=document.createElement('option');option.value=type;option.textContent=FEATURE_NAMES[type]||type;select.appendChild(option);select.value=type}startDrawing();if(matchMedia('(max-width: 760px)').matches)setToolbarCollapsed(true);updateToolbar()}
